fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toLong()

    val digits = n.toString().map { it - '0' }
    val len = digits.size

    // Precompute powers of 10 up to 10^10 (safe for n <= 1e9)
    val pow10 = LongArray(11)
    pow10[0] = 1L
    for (i in 1..10) pow10[i] = pow10[i - 1] * 10L

    var total = 0L

    // Count numbers with only one distinct digit
    fun countSingleDigit(): Long {
        var res = 0L
        for (d in 0..9) {
            if (d == 0) continue
            var cur = 0L
            var mul = 1L
            while (true) {
                cur = cur * 10 + d
                if (cur > n) break
                res++
            }
        }
        return res
    }

    // Count numbers with exactly two distinct digits x != y
    fun countTwoDigits(): Long {
        var res = 0L
        for (x in 0..9) {
            for (y in 0..9) {
                if (x == y) continue
                // For each length
                for (L in 1..len) {
                    // Leading digit cannot be 0
                    val digitsSet = arrayOf(x, y)
                    for (first in digitsSet) {
                        if (first == 0) continue
                        // DP[pos][mask]: count ways
                        // mask: bit0 for x used, bit1 for y used
                        val dp = Array(L + 1) { LongArray(4) }
                        val maskFirst = (if (first == x) 1 else 2)
                        dp[1][maskFirst] = 1L
                        for (pos in 1 until L) {
                            for (mask in 0..3) {
                                val cur = dp[pos][mask]
                                if (cur == 0L) continue
                                for (d in digitsSet) {
                                    val nmask = mask or (if (d == x) 1 else 2)
                                    dp[pos + 1][nmask] += cur
                                }
                            }
                        }
                        val countAll = dp[L][3] // both digits used
                        if (countAll == 0L) continue

                        // Now we need to count only those <= n
                        // For L < len, all are valid
                        if (L < len) {
                            res += countAll
                        } else {
                            // L == len: digit DP with upper bound
                            res += countBounded(x, y, first, L, digits, n)
                        }
                    }
                }
            }
        }
        return res
    }

    // Count numbers of length L, using digits x and y, starting with 'first',
    // using both digits at least once, and <= n
    fun countBounded(
        x: Int,
        y: Int,
        first: Int,
        L: Int,
        limitDigits: List<Int>,
        nVal: Long
    ): Long {
        val digitsSet = arrayOf(x, y)
        // dp[pos][mask][tight]
        val dp = Array(L + 1) { Array(4) { LongArray(2) } }
        val firstMask = if (first == x) 1 else 2
        val firstLimit = limitDigits[0]
        if (first > firstLimit) return 0L
        val tightInit = if (first == firstLimit) 1 else 0
        dp[1][firstMask][tightInit] = 1L

        for (pos in 1 until L) {
            val limitDigit = limitDigits[pos]
            for (mask in 0..3) {
                for (tight in 0..1) {
                    val cur = dp[pos][mask][tight]
                    if (cur == 0L) continue
                    val maxDigit = if (tight == 1) limitDigit else 9
                    for (d in digitsSet) {
                        if (d > maxDigit) continue
                        val nmask = mask or (if (d == x) 1 else 2)
                        val ntight = if (tight == 1 && d == maxDigit) 1 else 0
                        dp[pos + 1][nmask][ntight] += cur
                    }
                }
            }
        }
        return dp[L][3][0] + dp[L][3][1]
    }

    // Simpler approach: generate all numbers with <= 2 distinct digits via DFS and check <= n
    // Given constraints (n <= 1e9), this is easier and safe.
    fun bruteForce(): Long {
        val seen = HashSet<Long>()
        fun dfs(cur: Long, usedMask: Int) {
            if (cur > n) return
            if (cur != 0L) {
                // Check if usedMask has at most 2 bits set
                if (Integer.bitCount(usedMask) <= 2) {
                    seen.add(cur)
                }
            }
            if (cur > 0 && cur > n / 10) return
            for (d in 0..9) {
                val next = cur * 10 + d
                val nmask = if (cur == 0L && d == 0) usedMask else (usedMask or (1 shl d))
                if (Integer.bitCount(nmask) > 2) continue
                if (next == 0L) continue
                dfs(next, nmask)
            }
        }
        dfs(0L, 0)
        return seen.size.toLong()
    }

    // Use brute force generation (simple and safe for n <= 1e9)
    val answer = bruteForce()
    println(answer)
}

