    // Precompute combinations C[n][k] up to 10
    val maxN = 10
    val C = Array(maxN + 1) { LongArray(maxN + 1) }
    for (i in 0..maxN) {
        C[i][0] = 1
        C[i][i] = 1
        for (j in 1 until i) {
