        }
    }

    var ans = 0L

    // Count numbers with fewer digits
    for (d in 1 until len) {
        val total = 9L * (1L shl (d - 1)) + 1L
        ans += total
    }

    // Count numbers with same length using digit DP
    // dp[pos][state]: state 0..2 (0: one digit, 1: two digits, 2: >2 digits)
    val dp = Array(len + 1) { LongArray(3) }
    dp[0][0] = 1L

    for (pos in 0 until len) {
        val curDigit = s[pos] - '0'
        for (state in 0..2) {
            val curVal = dp[pos][state]
            if (curVal == 0L) continue
            for (d in 0..9) {
                if (pos == 0 && d == 0) continue
                if (d > curDigit) continue
                val nextState = when (state) {
                    0 -> 0 // first digit, still one distinct digit
                    1 -> 1 // two distinct digits
                    else -> 2
                }
                var ns = nextState
                if (pos == 0) {
                    // first digit always starts with one distinct digit
                    ns = 0
                } else {
                    // track distinct digits count implicitly:
                    // we don't know actual digits, but we only care if count >2
                    // However, we can't track exact digits, so we use combinatorial count instead.
                    // This DP is only to count numbers with at most 2 distinct digits.
                    // To do that, we must track actual digits; but since digits are 0..9, we use combinatorics instead.
                }
            }
        }
    }

    // The above DP approach is complex; instead, use combinatorics directly.

    // Count numbers of length len with at most 2 distinct digits and <= n
    // Enumerate all unordered pairs (x,y) with 0<=x<=y<=9, and also single-digit case (x=y).
    fun countForPair(x: Int, y: Int): Long {
        // Count numbers of length len, digits only x,y, no leading zero, <= n
        // Use DFS by positions.
        var res = 0L
        fun dfs(pos: Int, tight: Boolean, started: Boolean) {
            if (pos == len) {
                if (started) res++
                return
            }
            val limit = if (tight) s[pos] - '0' else 9
            val digits = intArrayOf(x, y).distinct().sorted()
            for (d in digits) {
                if (!started && d == 0) continue
                if (d > limit) continue
                val ntight = tight && (d == limit)
                dfs(pos + 1, ntight, started || d != 0)
            }
        }
        dfs(0, true, false)
        return res
    }

    var totalSameLen = 0L
    for (x in 0..9) {
        for (y in x..9) {
            totalSameLen += countForPair(x, y)
        }
    }

    ans += totalSameLen
    println(ans)
}

