fun countNumbersWithDigits(a: Int, b: Int, n: Long): Long {
    if (a == b) {
        // Only one digit allowed
        if (a == 0) return 0
        var cur = a.toLong()
        var res = 0L
        while (cur <= n) {
            res++
            cur = cur * 10 + a
        }
        return res
    }

    val digits = mutableListOf<Int>()
    var temp = n
    while (temp > 0) {
        digits.add((temp % 10).toInt())
        temp /= 10
    }
    digits.reverse()

    val memo = Array(digits.size + 1) { Array(2) { LongArray(2) { -1L } } }

    fun dfs(pos: Int, tight: Int, started: Int): Long {
        if (pos == digits.size) {
            return if (started == 1) 1L else 0L
        }
        val cached = memo[pos][tight][started]
        if (cached != -1L) return cached

        var res = 0L
        val limit = if (tight == 1) digits[pos] else 9

        if (started == 0) {
            // Option to not start yet (place 0)
            res += dfs(pos + 1, if (tight == 1 && 0 == limit) 1 else 0, 0)
            // Start with a or b if allowed
            if (a != 0 && a <= limit) {
                res += dfs(pos + 1, if (tight == 1 && a == limit) 1 else 0, 1)
            }
            if (b != 0 && b != a && b <= limit) {
                res += dfs(pos + 1, if (tight == 1 && b == limit) 1 else 0, 1)
            }
        } else {
            // Already started, can place only a or b
            if (a <= limit) {
                res += dfs(pos + 1, if (tight == 1 && a == limit) 1 else 0, 1)
            }
            if (b != a && b <= limit) {
                res += dfs(pos + 1, if (tight == 1 && b == limit) 1 else 0, 1)
            }
        }

        memo[pos][tight][started] = res
        return res
    }

    return dfs(0, 1, 0)
}

